import{_ as o,o as t,c as a,ag as s}from"./chunks/framework.B7PviQjB.js";const g=JSON.parse('{"title":"Troubleshooting","description":"Fix common startup, sign-in, sync, upload, and feature errors on a self-hosted Wafflebase.","frontmatter":{"title":"Troubleshooting","description":"Fix common startup, sign-in, sync, upload, and feature errors on a self-hosted Wafflebase.","type":"troubleshooting"},"headers":[],"relativePath":"developers/self-hosting/troubleshooting.md","filePath":"developers/self-hosting/troubleshooting.md"}'),i={name:"developers/self-hosting/troubleshooting.md"};function n(r,e,l,d,h,c){return t(),a("div",null,[...e[0]||(e[0]=[s('<h1 id="troubleshooting" tabindex="-1">Troubleshooting <a class="header-anchor" href="#troubleshooting" aria-label="Permalink to &quot;Troubleshooting&quot;">​</a></h1><p>Fix the errors operators most often see when running Wafflebase themselves. Find the message or symptom, then try the fixes in order.</p><h2 id="jwt-secret-is-required" tabindex="-1"><code>JWT_SECRET is required</code> <a class="header-anchor" href="#jwt-secret-is-required" aria-label="Permalink to &quot;`JWT_SECRET is required`&quot;">​</a></h2><p><strong>What it means:</strong> The backend exits at startup because <code>JWT_SECRET</code> is not set.</p><p><strong>Try this:</strong></p><ol><li>Set <code>JWT_SECRET</code> in <code>packages/backend/.env</code> or the container environment.</li><li>Restart the backend.</li></ol><h2 id="the-backend-fails-with-oauth2strategy-requires-a-clientid-option" tabindex="-1">The backend fails with <code>OAuth2Strategy requires a clientID option</code> <a class="header-anchor" href="#the-backend-fails-with-oauth2strategy-requires-a-clientid-option" aria-label="Permalink to &quot;The backend fails with `OAuth2Strategy requires a clientID option`&quot;">​</a></h2><p><strong>What it means:</strong> GitHub sign-in is always on, and <code>GITHUB_CLIENT_ID</code> is missing.</p><p><strong>Try this:</strong></p><ol><li>Set <code>GITHUB_CLIENT_ID</code>, <code>GITHUB_CLIENT_SECRET</code>, and <code>GITHUB_CALLBACK_URL</code>. See <a href="/docs/developers/self-hosting/sign-in.html#set-up-github-sign-in">Set up GitHub sign-in</a>.</li><li>Restart the backend.</li></ol><h2 id="the-app-loads-but-sign-in-and-sync-fail-for-everyone-else" tabindex="-1">The app loads but sign-in and sync fail for everyone else <a class="header-anchor" href="#the-app-loads-but-sign-in-and-sync-fail-for-everyone-else" aria-label="Permalink to &quot;The app loads but sign-in and sync fail for everyone else&quot;">​</a></h2><p><strong>What it means:</strong> The frontend was built without your URLs, so browsers call <code>http://localhost:3000</code> and <code>http://localhost:8080</code> on their own machines.</p><p><strong>Try this:</strong></p><ol><li>Search the app build for <code>localhost:3000</code>: <code>grep -rl --exclude-dir=docs &#39;localhost:3000&#39; packages/frontend/dist</code>. Any result means the build used the defaults.</li><li>Set <code>VITE_BACKEND_API_URL</code> and <code>VITE_YORKIE_RPC_ADDR</code> in <code>packages/frontend/.env.production.local</code> or on the build command. Do not use <code>.env.local</code>.</li><li>Rebuild and redeploy. See <a href="/docs/developers/self-hosting/deploy.html#build-the-frontend">Build the frontend</a>.</li></ol><h2 id="sign-in-returns-to-the-login-page-with-that-sign-in-link-expired" tabindex="-1">Sign-in returns to the login page with &quot;That sign-in link expired&quot; <a class="header-anchor" href="#sign-in-returns-to-the-login-page-with-that-sign-in-link-expired" aria-label="Permalink to &quot;Sign-in returns to the login page with &quot;That sign-in link expired&quot;&quot;">​</a></h2><p><strong>What it means:</strong> The browser dropped the sign-in state cookie. The usual cause is a <code>Secure</code> cookie on a plain-<code>http</code> origin, or sign-in started in another tab.</p><p><strong>Try this:</strong></p><ol><li>Sign in again from a single tab.</li><li>Check that <code>GITHUB_CALLBACK_URL</code> uses the scheme users actually reach. On plain <code>http</code>, it must start with <code>http://</code>.</li><li>If you set <code>COOKIE_SECURE=true</code>, make sure the site really is served over <code>https</code>.</li><li>Check that <code>FRONTEND_URL</code> matches the frontend origin exactly.</li></ol><h2 id="the-log-says-session-cookies-are-issued-without-secure" tabindex="-1">The log says session cookies are issued without <code>Secure</code> <a class="header-anchor" href="#the-log-says-session-cookies-are-issued-without-secure" aria-label="Permalink to &quot;The log says session cookies are issued without `Secure`&quot;">​</a></h2><p><strong>What it means:</strong> <code>NODE_ENV=production</code> with an <code>http://</code>, non-loopback <code>GITHUB_CALLBACK_URL</code>. Session cookies go out unprotected.</p><p><strong>Try this:</strong></p><ol><li>Set <code>GITHUB_CALLBACK_URL</code> to the <code>https://</code> URL users reach.</li><li>If TLS ends at a proxy and you cannot change the URL, set <code>COOKIE_SECURE=true</code>.</li></ol><h2 id="command-line-sign-in-requires-an-https-server" tabindex="-1"><code>Command-line sign-in requires an https server</code> <a class="header-anchor" href="#command-line-sign-in-requires-an-https-server" aria-label="Permalink to &quot;`Command-line sign-in requires an https server`&quot;">​</a></h2><p><strong>What it means:</strong> <code>wafflebase login</code> is refused because the backend cannot tell it is served over HTTPS.</p><p><strong>Try this:</strong></p><ol><li>Set <code>GITHUB_CALLBACK_URL</code> to an <code>https://</code> URL, or set <code>COOKIE_SECURE=true</code> behind a TLS proxy.</li><li>Or sign the CLI in with an API key instead. See <a href="/docs/developers/cli/">CLI</a>.</li></ol><h2 id="github-enterprise-sign-in-fails-with-bad-credentials" tabindex="-1">GitHub Enterprise sign-in fails with <code>Bad credentials</code> <a class="header-anchor" href="#github-enterprise-sign-in-fails-with-bad-credentials" aria-label="Permalink to &quot;GitHub Enterprise sign-in fails with `Bad credentials`&quot;">​</a></h2><p><strong>What it means:</strong> The email lookup went to github.com instead of your instance.</p><p><strong>Try this:</strong></p><ol><li>Set all four GitHub Enterprise URLs, including <code>GITHUB_USER_EMAIL_URL</code>. See <a href="/docs/developers/self-hosting/sign-in.html#use-github-enterprise">Use GitHub Enterprise</a>.</li><li>Restart the backend.</li></ol><h2 id="the-google-button-does-not-appear" tabindex="-1">The Google button does not appear <a class="header-anchor" href="#the-google-button-does-not-appear" aria-label="Permalink to &quot;The Google button does not appear&quot;">​</a></h2><p><strong>What it means:</strong> Google sign-in needs all three <code>GOOGLE_*</code> variables. The backend logs <code>Google sign-in is disabled:</code> with the missing names.</p><p><strong>Try this:</strong></p><ol><li>Set <code>GOOGLE_CLIENT_ID</code>, <code>GOOGLE_CLIENT_SECRET</code>, and <code>GOOGLE_CALLBACK_URL</code>.</li><li>Restart the backend and reload the sign-in page.</li></ol><h2 id="google-sign-in-fails-with-redirect-uri-mismatch" tabindex="-1">Google sign-in fails with <code>redirect_uri_mismatch</code> <a class="header-anchor" href="#google-sign-in-fails-with-redirect-uri-mismatch" aria-label="Permalink to &quot;Google sign-in fails with `redirect_uri_mismatch`&quot;">​</a></h2><p><strong>What it means:</strong> <code>GOOGLE_CALLBACK_URL</code> does not exactly match an authorized redirect URI on the Google OAuth client.</p><p><strong>Try this:</strong></p><ol><li>Copy <code>GOOGLE_CALLBACK_URL</code> into the client&#39;s authorized redirect URIs, including scheme and path.</li><li>Try again after Google saves the change.</li></ol><h2 id="uploads-fail-on-a-new-deployment" tabindex="-1">Uploads fail on a new deployment <a class="header-anchor" href="#uploads-fail-on-a-new-deployment" aria-label="Permalink to &quot;Uploads fail on a new deployment&quot;">​</a></h2><p><strong>What it means:</strong> With <code>NODE_ENV=production</code>, storage has no defaults, so the backend has no endpoint, bucket, or keys. The startup log shows a bucket warning.</p><p><strong>Try this:</strong></p><ol><li>Set all five <code>FILE_STORAGE_*</code> and all five <code>IMAGE_STORAGE_*</code> connection variables. See <a href="/docs/developers/self-hosting/deploy.html#set-up-blob-storage">Set up blob storage</a>.</li><li>Create the buckets, or give the credentials <code>s3:CreateBucket</code>.</li><li>Restart the backend and check the log for bucket warnings.</li></ol><h2 id="large-uploads-fail-with-413-or-file-too-large" tabindex="-1">Large uploads fail with <code>413</code> or <code>File too large</code> <a class="header-anchor" href="#large-uploads-fail-with-413-or-file-too-large" aria-label="Permalink to &quot;Large uploads fail with `413` or `File too large`&quot;">​</a></h2><p><strong>What it means:</strong> The file is over the limit (100 MB for files, 25 MB for image files, 10 MB for images inserted in documents), or your proxy&#39;s body limit is lower. The backend answers <code>413</code>, or <code>400 File too large (max 25 MB)</code> for an image file between 25 MB and 100 MB.</p><p><strong>Try this:</strong></p><ol><li>Check the file size against <a href="/docs/developers/self-hosting/deploy.html#set-up-blob-storage">the limits</a>.</li><li>Raise your proxy&#39;s request body limit to at least 100 MB.</li><li>For large imports through the API with inline images, raise <code>BACKEND_JSON_BODY_LIMIT</code>.</li></ol><h2 id="saving-a-database-connection-fails-with-a-server-error" tabindex="-1">Saving a database connection fails with a server error <a class="header-anchor" href="#saving-a-database-connection-fails-with-a-server-error" aria-label="Permalink to &quot;Saving a database connection fails with a server error&quot;">​</a></h2><p><strong>What it means:</strong> <code>DATASOURCE_ENCRYPTION_KEY</code> is missing or invalid. The backend log shows <code>DATASOURCE_ENCRYPTION_KEY environment variable is required</code>, or <code>DATASOURCE_ENCRYPTION_KEY must be a 64-character hex string (32 bytes)</code> when it has the wrong length or characters. The rest of the app works.</p><p><strong>Try this:</strong></p><ol><li>Generate a key with <code>openssl rand -hex 32</code> and set it.</li><li>Restart the backend.</li></ol><h2 id="lakehouse-reads-fail-on-a-server-without-internet-access" tabindex="-1">Lakehouse reads fail on a server without internet access <a class="header-anchor" href="#lakehouse-reads-fail-on-a-server-without-internet-access" aria-label="Permalink to &quot;Lakehouse reads fail on a server without internet access&quot;">​</a></h2><p><strong>What it means:</strong> DuckDB could not download an extension.</p><p><strong>Try this:</strong></p><ol><li>Use the production image, which already contains the extensions.</li><li>Or copy the extensions to a directory and set <code>LAKEHOUSE_DUCKDB_EXTENSION_DIR</code>. See <a href="/docs/developers/self-hosting/optional-features.html#run-the-lakehouse-without-internet-access">Run the lakehouse without internet access</a>.</li></ol><h2 id="a-lakehouse-connection-says-the-endpoint-is-not-allowed-by-the-server" tabindex="-1">A lakehouse connection says the endpoint <code>is not allowed by the server</code> <a class="header-anchor" href="#a-lakehouse-connection-says-the-endpoint-is-not-allowed-by-the-server" aria-label="Permalink to &quot;A lakehouse connection says the endpoint `is not allowed by the server`&quot;">​</a></h2><p><strong>What it means:</strong> The custom endpoint or catalog is not in <code>LAKEHOUSE_ALLOWED_ENDPOINTS</code>.</p><p><strong>Try this:</strong></p><ol><li>Add the exact origin, for example <code>https://s3.example.com</code>, to <code>LAKEHOUSE_ALLOWED_ENDPOINTS</code>.</li><li>Restart the backend.</li></ol><h2 id="the-log-says-shadow-mode" tabindex="-1">The log says <code>SHADOW mode</code> <a class="header-anchor" href="#the-log-says-shadow-mode" aria-label="Permalink to &quot;The log says `SHADOW mode`&quot;">​</a></h2><p><strong>What it means:</strong> <code>YORKIE_AUTH_WEBHOOK_ENFORCE=false</code> is set. Access decisions are logged but every request is allowed.</p><p><strong>Try this:</strong></p><ol><li>Unset <code>YORKIE_AUTH_WEBHOOK_ENFORCE</code>.</li><li>Restart the backend and check for <code>enforcing per-document access</code> in the log.</li></ol><h2 id="viewers-can-edit-documents" tabindex="-1">Viewers can edit documents <a class="header-anchor" href="#viewers-can-edit-documents" aria-label="Permalink to &quot;Viewers can edit documents&quot;">​</a></h2><p><strong>What it means:</strong> The Yorkie auth webhook is not registered, or the backend is in shadow mode.</p><p><strong>Try this:</strong></p><ol><li>Register the webhook methods. See <a href="/docs/developers/self-hosting/deploy.html#turn-on-per-document-access-control">Turn on per-document access control</a>.</li><li>Make sure <code>YORKIE_SECRET_KEY</code> is set and the log does not say <code>SHADOW mode</code>.</li></ol><h2 id="naming-a-version-fails-for-everyone" tabindex="-1">Naming a version fails for everyone <a class="header-anchor" href="#naming-a-version-fails-for-everyone" aria-label="Permalink to &quot;Naming a version fails for everyone&quot;">​</a></h2><p><strong>What it means:</strong> <code>CreateRevision</code> is registered on the Yorkie auth webhook.</p><p><strong>Try this:</strong></p><ol><li>Remove it: <code>yorkie project update &lt;project&gt; --auth-webhook-method-rm CreateRevision</code>.</li></ol><h2 id="the-documents-list-does-not-sort-by-last-edit" tabindex="-1">The documents list does not sort by last edit <a class="header-anchor" href="#the-documents-list-does-not-sort-by-last-edit" aria-label="Permalink to &quot;The documents list does not sort by last edit&quot;">​</a></h2><p><strong>What it means:</strong> The Yorkie event webhook is not registered, or <code>YORKIE_SECRET_KEY</code> is missing and the backend refuses it.</p><p><strong>Try this:</strong></p><ol><li>Set <code>YORKIE_SECRET_KEY</code>.</li><li>Register the event webhook. See <a href="/docs/developers/self-hosting/deploy.html#keep-the-documents-list-in-edit-order">Keep the documents list in edit order</a>.</li></ol><h2 id="the-public-template-gallery-stays-closed" tabindex="-1">The public template gallery stays closed <a class="header-anchor" href="#the-public-template-gallery-stays-closed" aria-label="Permalink to &quot;The public template gallery stays closed&quot;">​</a></h2><p><strong>What it means:</strong> Submitting to the public gallery needs reviewers and <code>YORKIE_AUTH_WEBHOOK_ENFORCE=true</code>.</p><p><strong>Try this:</strong></p><ol><li>Set <code>WAFFLEBASE_TEMPLATE_REVIEWER_IDS</code> to at least one user ID.</li><li>Set <code>YORKIE_AUTH_WEBHOOK_ENFORCE=true</code> exactly.</li><li>Restart the backend. See <a href="/docs/developers/self-hosting/optional-features.html#open-the-public-template-gallery">Open the public template gallery</a>.</li></ol><h2 id="still-stuck" tabindex="-1">Still stuck <a class="header-anchor" href="#still-stuck" aria-label="Permalink to &quot;Still stuck&quot;">​</a></h2><p>Check the backend log for the first error after startup, then search or open an issue on <a href="https://github.com/wafflebase/wafflebase/issues" target="_blank" rel="noreferrer">GitHub</a>. Include the message, your deployment method, and which optional features you turned on.</p><h2 id="related" tabindex="-1">Related <a class="header-anchor" href="#related" aria-label="Permalink to &quot;Related&quot;">​</a></h2><ul><li><a href="/docs/developers/self-hosting/configuration.html">Configuration</a> for every variable and its default.</li><li><a href="/docs/developers/self-hosting/deploy.html">Deploy to production</a> for the full setup.</li><li><a href="/docs/developers/self-hosting/sign-in.html">Sign-in providers</a> for OAuth and cookie setup.</li></ul>',82)])])}const p=o(i,[["render",n]]);export{g as __pageData,p as default};
